const {chromium}=require('playwright'),{pathToFileURL}=require('url'),path=require('path'),fs=require('fs');
(async()=>{const browser=await chromium.launch({args:['--no-sandbox']});try{
const p=await browser.newPage({viewport:{width:390,height:1000},reducedMotion:'no-preference'}),errors=[];p.on('pageerror',e=>errors.push(e.message));await p.goto(process.env.ART_SITE_URL||pathToFileURL(path.resolve('index.html')).href);await p.click('#learningTab');
for(const island of [0,1]){await p.evaluate(i=>DEUTSCH_JOURNEY.select(i),island);await p.locator('.expedition-board').scrollIntoViewIfNeeded();await p.waitForFunction(()=>document.querySelector('.expedition-board.motion-in-view'));const a=await p.evaluate(()=>({pulse:getComputedStyle(document.querySelector('.is-current .expedition-pin-number')).animationName,waves:getComputedStyle(document.querySelector('.expedition-board'),'::before').animationName}));if(a.pulse!=='next-stop'||a.waves!=='shore-ripple')throw Error('Missing live map animation');}
await p.locator('[data-motion-toggle]').click();if(await p.locator('#learningView').getAttribute('data-motion')!=='off')throw Error('Motion toggle failed');if(await p.evaluate(()=>getComputedStyle(document.querySelector('.is-current .expedition-pin-number')).animationName)!=='none')throw Error('Motion off still animates');await p.reload();await p.click('#learningTab');if(await p.locator('#learningView').getAttribute('data-motion')!=='off')throw Error('Motion preference lost');await p.locator('[data-motion-toggle]').click();await p.emulateMedia({reducedMotion:'reduce'});await p.waitForFunction(()=>document.querySelector('#learningView').dataset.motion==='off');if(!await p.locator('[data-motion-toggle]').isDisabled())throw Error('System reduced motion ignored');await p.emulateMedia({reducedMotion:'no-preference'});await p.waitForFunction(()=>document.querySelector('#learningView').dataset.motion==='on');
await p.evaluate(()=>{DEUTSCH_JOURNEY.select(0);DEUTSCH_JOURNEY.open(0);document.querySelector('#alContinue').click()});await p.evaluate(()=>{window.speak=()=>Promise.resolve();window.tone=()=>{};const s=DEUTSCH_ADAPTIVE.snapshot(),q=s.queue[s.index];DEUTSCH_ADAPTIVE.answer(q.type==='ua'||q.type==='listen'?q.c.ua:q.c.de)});if(await p.locator('#alFeedback').evaluate(e=>getComputedStyle(e).animationName)!=='answer-yes')throw Error('Missing correct response motion');await p.evaluate(()=>{document.querySelector('#alNext').click();DEUTSCH_ADAPTIVE.answer('wrong')});if(await p.locator('#alFeedback').evaluate(e=>getComputedStyle(e).animationName)!=='answer-retry')throw Error('Missing incorrect response motion');await p.emulateMedia({reducedMotion:'reduce'});if(await p.locator('#alFeedback').evaluate(e=>getComputedStyle(e).animationName)!=='none')throw Error('Reduced motion still shakes answer');await p.emulateMedia({reducedMotion:'no-preference'});
for(const width of [320,390,768,1280]){await p.setViewportSize({width,height:1000});await p.evaluate(()=>DEUTSCH_JOURNEY.select(0));if(await p.evaluate(()=>document.documentElement.scrollWidth>innerWidth+1))throw Error('Animated map overflow '+width);if(width===390){fs.mkdirSync('audit-screenshots',{recursive:true});await p.locator('.expedition-board').screenshot({path:'audit-screenshots/animated-map.png'})}}
await p.evaluate(()=>{document.documentElement.lang='en';DEUTSCH_JOURNEY.select(1)});await p.waitForFunction(()=>document.querySelector('[data-motion-toggle]').textContent==='Animations on');if(errors.length)throw Error(errors.join(';'));console.log('PASS living maps and lessons: both islands, next-stop pulse, waves, feedback reactions, persistent toggle, system reduced motion, responsive layout and localization');
}finally{await browser.close()}})().catch(e=>{console.error(e);process.exit(1)});
